import React, { useState, useEffect } from 'react';
import api from '../api';

function Templates() {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    frequency: 'daily'
  });
  const [showOneOffForm, setShowOneOffForm] = useState(false);
  const [oneOffData, setOneOffData] = useState({
    title: '',
    description: '',
    frequency: 'daily',
    due_date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    loadTemplates();
  }, []);

  const loadTemplates = async () => {
    setLoading(true);
    try {
      const data = await api.getTemplates();
      setTemplates(data);
    } catch (error) {
      console.error('Error loading templates:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTemplate = async (e) => {
    e.preventDefault();
    try {
      await api.createTemplate(formData);
      setFormData({ title: '', description: '', frequency: 'daily' });
      setShowForm(false);
      loadTemplates();
    } catch (error) {
      console.error('Error creating template:', error);
    }
  };

  const handleToggleActive = async (template) => {
    try {
      await api.updateTemplate(template.id, {
        ...template,
        is_active: template.is_active ? 0 : 1
      });
      loadTemplates();
    } catch (error) {
      console.error('Error updating template:', error);
    }
  };

  const handleCreateOneOff = async (e) => {
    e.preventDefault();
    try {
      await api.createOneOffTask(oneOffData);
      setOneOffData({
        title: '',
        description: '',
        frequency: 'daily',
        due_date: new Date().toISOString().split('T')[0]
      });
      setShowOneOffForm(false);
      alert('One-off task created successfully!');
    } catch (error) {
      console.error('Error creating one-off task:', error);
    }
  };

  if (loading) {
    return <div className="loading">Loading templates...</div>;
  }

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>Manage Templates</h1>
        <p>Create and manage recurring task templates</p>
      </div>

      <div style={{ display: 'flex', gap: '10px', marginBottom: '30px' }}>
        <button className="btn btn-primary" onClick={() => setShowForm(!showForm)}>
          {showForm ? 'Cancel' : '+ New Template'}
        </button>
        <button className="btn btn-success" onClick={() => setShowOneOffForm(!showOneOffForm)}>
          {showOneOffForm ? 'Cancel' : '+ One-Off Task'}
        </button>
      </div>

      {showForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Create New Template</h3>
          <form onSubmit={handleCreateTemplate}>
            <div className="form-group">
              <label>Title</label>
              <input
                type="text"
                className="form-control"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                required
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                className="form-control"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              />
            </div>
            <div className="form-group">
              <label>Frequency</label>
              <select
                className="form-control"
                value={formData.frequency}
                onChange={(e) => setFormData({ ...formData, frequency: e.target.value })}
              >
                <option value="daily">Daily</option>
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </div>
            <button type="submit" className="btn btn-primary">
              Create Template
            </button>
          </form>
        </div>
      )}

      {showOneOffForm && (
        <div className="task-section" style={{ marginBottom: '30px' }}>
          <h3 style={{ marginBottom: '20px' }}>Create One-Off Task</h3>
          <form onSubmit={handleCreateOneOff}>
            <div className="form-group">
              <label>Title</label>
              <input
                type="text"
                className="form-control"
                value={oneOffData.title}
                onChange={(e) => setOneOffData({ ...oneOffData, title: e.target.value })}
                required
              />
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                className="form-control"
                value={oneOffData.description}
                onChange={(e) => setOneOffData({ ...oneOffData, description: e.target.value })}
              />
            </div>
            <div className="form-group">
              <label>Frequency Type</label>
              <select
                className="form-control"
                value={oneOffData.frequency}
                onChange={(e) => setOneOffData({ ...oneOffData, frequency: e.target.value })}
              >
                <option value="daily">Daily</option>
                <option value="weekly">Weekly</option>
                <option value="monthly">Monthly</option>
              </select>
            </div>
            <div className="form-group">
              <label>Due Date</label>
              <input
                type="date"
                className="form-control"
                value={oneOffData.due_date}
                onChange={(e) => setOneOffData({ ...oneOffData, due_date: e.target.value })}
                required
              />
            </div>
            <button type="submit" className="btn btn-success">
              Create One-Off Task
            </button>
          </form>
        </div>
      )}

      <div className="task-section">
        <h2 style={{ marginBottom: '20px' }}>Existing Templates</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {templates.map(template => (
            <div
              key={template.id}
              style={{
                border: '1px solid #e0e0e0',
                borderRadius: '6px',
                padding: '15px',
                backgroundColor: template.is_active ? 'white' : '#f5f5f5'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
                <div style={{ flex: 1 }}>
                  <h4 style={{ marginBottom: '5px' }}>{template.title}</h4>
                  <p style={{ color: '#7f8c8d', fontSize: '14px', marginBottom: '10px' }}>
                    {template.description}
                  </p>
                  <div style={{ display: 'flex', gap: '15px', fontSize: '14px' }}>
                    <span>
                      <strong>Frequency:</strong> {template.frequency}
                    </span>
                    <span>
                      <strong>Status:</strong>{' '}
                      <span style={{ color: template.is_active ? '#27ae60' : '#e74c3c' }}>
                        {template.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </span>
                  </div>
                </div>
                <button
                  className={`btn ${template.is_active ? 'btn-secondary' : 'btn-success'}`}
                  onClick={() => handleToggleActive(template)}
                >
                  {template.is_active ? 'Deactivate' : 'Activate'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Templates;
